insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-skyline-skipped-compare-page-s687','decision','Skyline skipped: both candidate programs point at a compare page','S687: Skyline''s paid read (claude/reread-skyline-s687, run 44586737073) filed only a capture-only preview. Both candidate programs, 30882 Mathematics and 45698 Engineering, point to _compare.new.programs.php, a page that compares many programs, so neither is the program''s own page and nothing was posted. Skyline is skipped until a page of its own is found.',array['program-requirements','reread','skyline'],'proposed','#3565; run 44586737073','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('d-rule-d-from-committed-previews-s687','decision','Rule D''s marks are read from the committed capture files','S687: kb/_program_discontinued.py gains committed_not_printed, which reads rule D''s marks from committed capture files; only each college''s newest read by run counts (COBIx on #3569). Free capture-only previews with rule_d=1 ran at College of the Desert, CCSF and Santa Rosa Junior. The 8 not printed are prior-year-read candidates (CAPTURE_PRIOR), never flags.',array['program-requirements','rule-d','discontinued'],'proposed','#3569 (3cbf7012)','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('d-feather-palomar-trials-off-wave-s687','decision','Feather River''s full read and the two outline trials stay off the wave','S687: the wave (#3565) left out Feather River''s full read kb/course_outcomes/frc/read_44535960153_p1of1.json and both trials (44534888428, 44536105509). They fail the standing test''s check 4 (SLOs filed with no objectives; f-outline-readers-need-header-fixes-s685) and stay on their claude/slo-* branches until the reader fixes land, then are re-added.',array['course-outcomes','slo','outline-reader'],'proposed','#3565 (b63a4ba9)','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('d-display-keyset-confirm-s687','decision','The display apply''s confirming read pages by key, never by offset','S687: #3564 (bc0bf6ee) pages the display apply''s confirming read by key, as COBIx suspected on #3556; a page with no new key stops the read, and the check is collation-independent (COBIx''s second review on #3564). Build 3361e3aa5b7d then confirmed on its own read, the first full build to do so; S685''s offset-paged read had answered HTTP 500.',array['program-requirements','display','supabase'],'proposed','#3564; #3567','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('d-commons-needs-you-ranking-s687','decision','Needs you takes COBIx''s ranking; two items stay off the page','S687: Commons Needs you (#3570, c2ef4ce1; issue #3566, Sam''s requirement of Nov 19 10:36 AM PT) follows the ranking COBIx proposed, with the college wording rule first under Decisions waiting. The conductor-model flip on the routine''s form and the ask for Malone stay off the page: neither is a call the page can carry to an answer.',array['commons','needs-you','ui'],'proposed','#3570; issue #3566','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('d-wording-rule-write-to-second-session-s687','decision','The wording-rule write belongs to the second S687 session','S687: Sam, Nov 19 12:42 PM PT, relayed by COBIx on #3566: "Forward all your recommendations and yes on the 36." A yes to the college wording rule for the 36 C-ID CR groups at #cr-reference/names. One writer per file: a second S687 session holds the cr_reference_decisions write, the sam_rulings.md row and its own memory row; SkyPipit wrote none.',array['cr-reference','commons','coordination'],'proposed','#3566 comment 7021717277','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('p-read-dispatches-share-group-s687','pitfall','Reads dispatched together on one branch cancel each other','S687: three read dispatches on one branch share a concurrency group, and GitHub keeps one pending run per group: the middle one (Santa Rosa Junior, run 44596607977) was canceled when the third arrived. Space the dispatches out, or put them on separate branches, and confirm each run started before sending the next.',array['github-actions','program-requirements','dispatch'],'proposed','run 44596607977','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('p-fake-table-ignores-keyset-s687','pitfall','A test fake keyed on offset looped once the reader paged by key','S687: a store test''s fake table answered pages by offset=. Once the display reader paged by key (#3564), the fake returned the same page forever and the lints job hung 55 minutes (run 44585137180, canceled). A fake must follow the paging the reader sends, and a reader should stop on a page with no new key.',array['tests','display','ci'],'proposed','#3564; run 44585137180','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('p-stash-unstaged-commit-s687','pitfall','A stash and pop between git add and git commit unstaged half a commit','S687: a git stash and pop between git add and git commit left the code half of #3569''s first commit unstaged, so the commit carried only part of the change. COBIx caught it in review. Commit straight after git add, and read git show --stat before pushing.',array['git','process'],'proposed','#3569','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('p-sources-from-needs-filed-preview-s687','pitfall','A sources_from read is refused unless the branch files that run''s preview','S687: a program-requirements read with sources_from is refused unless the branch it runs on files that run''s preview. File the preview on the branch first, then dispatch the sources_from read there.',array['program-requirements','dispatch'],'proposed','S687 session','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('p-artifact-host-blocked-s687','pitfall','The sandbox cannot download GitHub run artifacts','S687: the session sandbox cannot download a workflow run''s artifacts; the blob host they are served from is blocked by the proxy. Read a run through its committed receipt, its log or a migrate-runner read instead of planning on the artifact.',array['sandbox','github-actions'],'proposed','S687 session','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('f-rule-d-cannot-reach-dropped-records-s687','fact','Rule D cannot reach records whose files the filing dropped','S687 finding: rule D reads only committed records that place no courses, so the programs whose record files S683''s filing dropped while their live rows stayed are out of its reach (City College of San Francisco''s 20 no-page programs). They need another path, such as a read that files those records again.',array['program-requirements','rule-d','finding'],'proposed','#3569; kb/status/program_discontinued.json','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('m-nine-colleges-posted-s687','milestone','S685''s nine-college reread posted and loaded','S687 (Sam: "keep rolling, merge them when green"): wave #3565 (b63a4ba9) posted the nine-college reread, 164 rows replaced and 45 inserted, every receipt''s error null. American River 104/18, Modesto Junior 13/2, Woodland 15/1, Cerritos 15/0, Imperial Valley 7/0, Yuba 6/4, Southwestern 4/16, Grossmont 0/1, MiraCosta 0/3. Cerritos 44984 held for a person.',array['program-requirements','reread','wave'],'proposed','#3565; runs 44582982949, 44583388525','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('m-display-3361e3aa5b7d-confirmed-s687','milestone','Display build 3361e3aa5b7d confirmed on its own read','S687: #3567 (52d85a7e), 18,380 statements: one college (run 44600185371, 125/125), the gate (44600769857), the whole build (44601141904: 18,255 written, 125 current, 0 errors, confirmed in under 4 minutes), the closing count (44602140198: 18,380 at the new build, 15 at bef8ef819af7, 16 at 0874a3a15f22). The first full build to confirm on its own read.',array['program-requirements','display'],'proposed','#3567; run 44601141904','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19'),
('m-census-5145-s687','milestone','The harvest gap census: 5,145 programs left','S687: harvest-gap-census.yml on main ab6bf57b (run 44604899544): 5,145 left against 5,203 at S685 (58 fewer); passing 15,044 of 20,282, up from 14,986.',array['program-requirements','census'],'proposed','run 44604899544','SkyPipit (S687), Sam''s session',null,'SkyPipit (S687)',date '2026-11-19')
